boolean def merchantEligible(int:creditScore, int:breaches, boolean:bondPaid) {
    if (creditScore >= 80) {
        if (breaches == 0) {
            if (bondPaid) {
                return true;
            } else {
                return false;
            }
        } else {
            return false;
        }
    } else {
        return false;
    }
}


int def availableStock(int:stockOnHand, int:reservedStock) {
    return stockOnHand - reservedStock;
}


str def depositTreatment(int:windowStatus, boolean:identity, boolean:cancelledBefore) {
    if (cancelledBefore) {
        return "REFUNDABLE";
    } else if (windowStatus == 2) {
        return "FORFEIT";
    } else if (windowStatus == 1) {
        if (identity) {
            return "DEDUCT";
        } else {
            return "HOLD";
        }
    } else {
        return "HOLD";
    }
}


boolean def canPayBalance(int:windowStatus, boolean:identity) {
    if (windowStatus == 1) {
        if (identity) {
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}
